-- Utility function to randomly seed 194 themed stakes
CREATE OR REPLACE FUNCTION populate_random_stakes()
RETURNS void AS $$
DECLARE
    usernames TEXT[] := ARRAY[
        'pegleg_pete', 'blackbeard_bob', 'rumrunner_jack', 'seawitch_sally',
        'hookhand_joe', 'sirens_song', 'barnacle_bill', 'flintlock_fiona',
        'coral_cleo', 'krakenbait_kyle', 'poopdeck_paul', 'mainsail_mary',
        'cutlass_craig', 'ghost_greta', 'doubloon_dan', 'cannonade_clara'
    ];
    contestant_ids TEXT[] := ARRAY['c1', 'c2', 'c3', 'c4', 'c5', 'c6'];
    i INT := 0;
    picked_username TEXT;
    picked_contestant TEXT;
    picked_amount INT;
BEGIN
    FOR i IN 1..194 LOOP
        picked_username := usernames[ceil(random() * array_length(usernames, 1))::INT];
        picked_contestant := contestant_ids[ceil(random() * array_length(contestant_ids, 1))::INT];
        picked_amount := floor(random() * 20 + 1)::INT; -- Amount: 1 to 20 coins

        -- Ensure the user exists (create if needed)
        PERFORM 1 FROM accounts WHERE username = picked_username;
        IF NOT FOUND THEN
            INSERT INTO accounts (username, password_hash, coins)
            VALUES (
                picked_username,
                '$2b$10$QJ8YnBtqOWHjkIyBxPu.8K9QxQxQxQxQxQxQxQxQxQxQxQxQxQxX', -- hash of "pirate123"
                200
            );
        END IF;

        -- Deduct coins if sufficient, then insert stake
        BEGIN
            UPDATE accounts SET coins = coins - picked_amount
            WHERE username = picked_username AND coins >= picked_amount;

            IF FOUND THEN
                INSERT INTO stakes (username, contestant_id, amount)
                VALUES (picked_username, picked_contestant, picked_amount);
            END IF;
        EXCEPTION WHEN OTHERS THEN
            -- ignore row if something fails (e.g., foreign key removed or coins too low)
        END;
    END LOOP;
END;
$$ LANGUAGE plpgsql;

