    try {
      const account = await ContestDatabase.getAccount(username);
      if (!account) {
        throw new Error("Account not found");
      }

      const token = this.generateToken(username);
      const expiresAt = new Date(Date.now() + 24 * 60 * 60 * 1000);

      const sessionId = await ContestDatabase.createSession(
        username,
